-- constructor 는 as 를 무시한다

@Test
void constructor_별칭() {
    em.clear();
    UserDto a = queryFactory
            .select(Projections.constructor(UserDto.class,
                    member.username, member.age))
            .from(member).where(member.username.eq("m1")).fetchOne();

    em.clear();
    UserDto b = queryFactory
            .select(Projections.constructor(UserDto.class,
                    member.username.as("엉뚱한이름"), member.age))
            .from(member).where(member.username.eq("m1")).fetchOne();

    System.out.println("as 없이: " + a.getName());
    System.out.println("as 있고: " + b.getName());
}

