// UserDto 의 name 을 nickname 으로 리팩터링

@Test
void 리팩터링_후() {
    em.clear();
    UserDto d = queryFactory
            .select(Projections.fields(UserDto.class,
                    member.username.as("name"),      // 안 고쳤다
                    member.age))
            .from(member).where(member.username.eq("m1")).fetchOne();
    System.out.println("nickname: " + d.getNickname());
}

